var opponentReportKey=null,opponentMatchContext=null;
function renderOpponentReport(){
 const host=document.getElementById('opposition-report');if(!host||host.hidden||view!=='match'||!state)return;
 const key=[season.year,season.round,season.competition,state.seed,state.minute,state.tactic,state.lineup.map(id=>id+':'+state.players[id].energy).join(',')].join('|');if(key===opponentReportKey)return;
 const d=Opposition.read(season);if(!d.valid){host.innerHTML='';return;}opponentReportKey=key;
 const text=matchdayText,n=n=>Math.round(n),plan=typeof TacticsBoard!=='undefined'?TacticsBoard.read(season):null,keyPlayer=d.keyPlayer,keyRow=keyPlayer&&d.lineup.find(p=>p.id===keyPlayer.id);
 const keyPlayerMarkup=keyPlayer?'<article class="opposition-key-player" aria-label="요주의 선수 '+text(keyPlayer.name)+'"><div class="opposition-key-marker" aria-hidden="true"><span>'+text(keyRow?.no||'★')+'</span><small>KEY</small></div><div class="opposition-key-copy"><div><span>요주의 선수</span><b>'+text(keyPlayer.role)+'</b></div><h3>'+text(keyPlayer.name)+'</h3><p>'+text(keyPlayer.pos)+' · 종합 '+n(keyPlayer.overall)+' · '+text(keyPlayer.threat)+'</p></div><span class="opposition-key-focus">상대 전술의 중심</span></article>':'';
 const discipline=d.rivalDiscipline||{rows:[],absent:[],applicable:false},disciplineMarkup=discipline.rows.length?'<div class="opposition-discipline"><b>리그 경고·출전 정지</b><span>'+discipline.rows.map(row=>text(row.name)+' · '+(row.pending?(discipline.applicable?'이번 리그전 결장':'다음 리그전 정지 대기')+' · ':'')+(row.yellows?'경고 '+row.yellows+'/3':'퇴장 정지')).join('　·　')+'</span></div>':'';
 const reference=d.club.reference?'<span>실제 구단 전력 참고 <b>'+text(d.club.reference)+'</b></span>':'<span>구단 전력 <b>창작 팀 기준</b></span>';
 const rows=d.lineup.map(p=>{const featured=keyPlayer?.id===p.id,cardId=p.replacementFor?'opp'+(p.no-1):p.id,card=typeof matchdayCardInfo==='function'?matchdayCardInfo(cardId,1):{markup:''},classes=[p.dismissed?'opposition-dismissed':'',featured?'opposition-key-row':'',p.replacementFor?'opposition-reserve-row':''].filter(Boolean).join(' ');return '<tr'+(classes?' class="'+classes+'"':'')+'><td><i>'+p.no+'</i>'+Portraits.html(p)+'<span class="opposition-player-name">'+text(p.name)+(featured?'<em class="opposition-key-badge">요주의</em>':'')+'<small>'+p.pos+' · '+p.primaryLabel+'</small>'+(p.replacementFor?'<small class="opposition-reserve-note">'+text(p.replacementFor)+' 누적 정지 · 후보 출전</small>':'')+card.markup+'</span></td><td><b class="opposition-overall">'+p.overall+'</b></td><td>'+p.primary+'</td><td>'+p.speed+'</td><td>'+p.endurance+'</td><td><b>'+n(p.energy)+'</b><small>'+(p.dismissed?'퇴장':p.condition)+'</small></td></tr>';}).join('');
 host.innerHTML='<section class="opposition-card"><header><div><span class="eyebrow">OPPOSITION / '+(state.phase==='prep'?'킥오프 전':'경기 중')+'</span><h2>'+text(d.club.name)+'</h2><p>'+text(d.plan.description)+'</p></div><span class="opposition-crest" style="background:'+d.club.color+'">'+text(d.club.code)+'</span></header><div class="opposition-plan"><span>포메이션 <b>'+d.plan.formation.split('').join('–')+'</b></span><span>전술 성향 <b>'+text(d.plan.label)+'</b></span>'+reference+'<span>리그 최근 경기 <b>'+text(d.recent.join(' · ')||'기록 없음')+'</b></span></div>'+disciplineMarkup+keyPlayerMarkup+'<div class="opposition-condition"><span>상대 체력 <b>'+n(d.condition.opponent)+'</b></span><span>활동 인원 <b>'+d.activePlayers.ours+' : '+d.activePlayers.opponent+'</b></span><span>우리 활동 선수 <b>'+n(d.condition.ours)+'</b></span><span>체력 주의 <b>'+d.condition.tired+'명</b></span></div><div class="opposition-comparisons">'+d.comparisons.map(r=>'<div><span>'+r.label+'</span><b>'+n(r.ours)+' <i>:</i> '+n(r.opponent)+'</b><small>우리 / 상대</small></div>').join('')+'</div><p class="opposition-advice">'+text(d.advice)+(plan?.valid?' <strong>코치 제안: '+text(plan.recommendation.label)+'</strong>':'')+'</p><div class="opposition-roster-heading"><h3>'+(state.phase==='prep'?'상대 예상 선발':'상대 선발')+' 11명</h3><span>포지션별 종합 능력 · 경기 중 체력 감소</span></div><table class="opposition-roster"><thead><tr><th>선수 / 포지션</th><th><abbr title="포지션 주요 능력을 가중한 1~99 종합 지수">종합</abbr></th><th>주능력</th><th>속도</th><th>지구력</th><th>체력</th></tr></thead><tbody>'+rows+'</tbody></table><p class="opposition-note">'+(season.suspensions?'우리 구단은 대회별 경고 3회·퇴장 시 대회별 정지를 적용합니다.':'우리 구단은 카드 누적 정지를 홈의 출전 정지 규칙에서 적용합니다.')+' 상대 구단은 리그 경기의 누적 경고 3회·퇴장을 다음 리그 경기에 반영합니다. 컵·유럽 상대 누적은 아직 포함하지 않습니다. 종합 능력은 포지션별 창작 가중치이며 실제 선수 평점이나 실시간 데이터가 아닙니다. 위의 빠른 전술로 지시를 바꾸거나 전술 분석에서 비교하세요.</p></section>';
}
